drop trigger if exists "on_contact_notes_attachments_updated_delete_note_attachments" on "public"."contact_notes";

drop trigger if exists "on_contact_notes_deleted_delete_note_attachments" on "public"."contact_notes";

drop trigger if exists "on_deal_notes_attachments_updated_delete_note_attachments" on "public"."deal_notes";

drop trigger if exists "on_deal_notes_deleted_delete_note_attachments" on "public"."deal_notes";

drop function if exists "public"."cleanup_note_attachments"();


  create table "public"."note_attachments_cleanup_queue" (
    "id" bigint generated by default as identity not null,
    "attachments" jsonb[] not null,
    "created_at" timestamp with time zone not null default now()
      );


alter table "public"."note_attachments_cleanup_queue" enable row level security;

CREATE UNIQUE INDEX note_attachments_cleanup_queue_pkey ON public.note_attachments_cleanup_queue USING btree (id);

alter table "public"."note_attachments_cleanup_queue" add constraint "note_attachments_cleanup_queue_pkey" PRIMARY KEY using index "note_attachments_cleanup_queue_pkey";

set check_function_bodies = off;

CREATE OR REPLACE FUNCTION public.enqueue_note_attachments_cleanup()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
    DECLARE
      enqueued_count integer;
    BEGIN
      IF TG_OP = 'DELETE' THEN
        INSERT INTO public.note_attachments_cleanup_queue (attachments)
        SELECT old_note.attachments
        FROM old_table AS old_note
        WHERE cardinality(old_note.attachments) > 0;
      ELSE
        INSERT INTO public.note_attachments_cleanup_queue (attachments)
        SELECT old_note.attachments
        FROM old_table AS old_note
        JOIN new_table AS new_note ON new_note.id = old_note.id
        WHERE old_note.attachments IS DISTINCT FROM new_note.attachments
          AND cardinality(old_note.attachments) > 0;
      END IF;

      GET DIAGNOSTICS enqueued_count = ROW_COUNT;

      IF enqueued_count > 0 THEN
        PERFORM net.http_post(
          url := public.get_note_attachments_function_url(),
          body := '{}'::jsonb,
          params := '{}'::jsonb,
          headers := '{"Content-Type": "application/json"}'::jsonb,
          timeout_milliseconds := 10000
        );
      END IF;

      RETURN NULL;
    END;
    $function$
;

revoke all on function public.enqueue_note_attachments_cleanup() from public, anon, authenticated;
grant all on function public.enqueue_note_attachments_cleanup() to service_role;

revoke all on table public.note_attachments_cleanup_queue from anon, authenticated;
grant all on table public.note_attachments_cleanup_queue to service_role;

revoke all on sequence public.note_attachments_cleanup_queue_id_seq from anon, authenticated;
grant all on sequence public.note_attachments_cleanup_queue_id_seq to service_role;

CREATE TRIGGER on_contact_notes_attachments_updated_delete_note_attachments AFTER UPDATE ON public.contact_notes REFERENCING OLD TABLE AS old_table NEW TABLE AS new_table FOR EACH STATEMENT EXECUTE FUNCTION public.enqueue_note_attachments_cleanup();

CREATE TRIGGER on_contact_notes_deleted_delete_note_attachments AFTER DELETE ON public.contact_notes REFERENCING OLD TABLE AS old_table FOR EACH STATEMENT EXECUTE FUNCTION public.enqueue_note_attachments_cleanup();

CREATE TRIGGER on_deal_notes_attachments_updated_delete_note_attachments AFTER UPDATE ON public.deal_notes REFERENCING OLD TABLE AS old_table NEW TABLE AS new_table FOR EACH STATEMENT EXECUTE FUNCTION public.enqueue_note_attachments_cleanup();

CREATE TRIGGER on_deal_notes_deleted_delete_note_attachments AFTER DELETE ON public.deal_notes REFERENCING OLD TABLE AS old_table FOR EACH STATEMENT EXECUTE FUNCTION public.enqueue_note_attachments_cleanup();
